const stages=[
 {title:'看得见、算得清',time:'0—2年 · 安排窗口，不是预测',goal:'先建立对真实系统的可见性。',text:'知道设备在哪里、谁维护、能耗多少、故障为何发生、资金从哪里来；AI首先帮助整理和连接分散信息，而不是替代现场事实。',assets:'资产与故障台账、土地和水资源约束、需求订单、财务与采购、质量记录。',ai:'多语言文档结构化、资产记录核对、异常线索、需求与采购整理。',gates:['关键资产、责任人与账款可追溯','水电、土地、环境与基本服务边界已明确','没有订单或运维预算的扩张已停止'],stop:'没有真实台账时，不把AI生成的“数字孪生”当成工厂本身。'},
 {title:'能运行、能修复',time:'1—4年 · 能力成熟前不跳关',goal:'让第一套设备不因一个小故障而失去功能。',text:'稳定电、水、通信、维修和备件。维护知识进入本地团队，关键工序建立人工接管和停机条件。',assets:'维修站、计量工具、标准备件、故障工单、维护资金、供应商替代方案。',ai:'辅助故障诊断、维修训练、工艺文档和PLC代码；所有安全放行经人和试验确认。',gates:['至少12个月运维与关键备件资金已落实','当地团队完成重复故障的独立诊断与恢复','供应商停服后的手工/离线接管已演练'],stop:'本系统不生成或批准安全关键控制代码；维修建议必须有现场检验。'},
 {title:'基本产品稳定交付',time:'3—8年 · 以合格率和回款为准',goal:'从“生产出来”走向“客户持续愿意购买”。',text:'农食、冷链、建材、包装、金属结构和普通机电服务形成可持续经营。产品标准、采购、质量和订单共同构成生产能力。',assets:'订单与回款、产品认证、可追溯批次、库存与物流、客户反馈和保修准备。',ai:'排产、视觉辅助质检、节能、库存预测与跨语言客户服务。',gates:['有稳定客户与可核实的回款','合格率、返工率与保修成本达标','出口净收益或进口节约基线可核实'],stop:'产量增加但卖不出去，或者进口节约没有原进口基线，都不计为现金来源。'},
 {title:'能改造、能复制',time:'6—15年 · “第二座工厂”的检验',goal:'让维护能力开始成为资本品能力。',text:'工装、一般零件、电柜、机电翻新、设备集成和计量服务在多个行业复用；设计方案、测试过程和本地技能一起复制。',assets:'工艺包、治具、测试台、供应商认证、通用件目录、完整维护文档。',ai:'设计与仿真、工艺参数优化、试验方案、标准件替代与产线协同。',gates:['本地团队能复刻一套经验证的标准产线','更新准备与关键进口外汇可以覆盖','跨行业供应商通过质量与交付验收'],stop:'不把仅仅组装进口整套模块，自动计作掌握其底层制造能力。'},
 {title:'选择性进入复杂产业',time:'10—25年以上 · 只进入有理由的领域',goal:'依据规模、资源与市场选择，而非追求完整产业清单。',text:'材料、化工、电机、专业机械、电子装配等方向，要经过市场、可靠能源、人才、质量体系与融资的共同检验。',assets:'专业研发、标准认证、规模市场、生态与社会许可、可撤退的投资计划。',ai:'复杂工程协作、设计空间探索、工业组织和知识积累；仍须独立验证。',gates:['规模市场、成本竞争力与质量认证已成立','人才、可靠供能、生态与社会许可已落实','资本回收、风险缓冲与失败退出机制明确'],stop:'先进fab、航空发动机等不是每个地区必须通过的通用关卡。'}
];
