<div class="question-grid">${D.questions.map(q=>`<details class="card"><summary><span class="tag">${q.id}</span> ${esc(q.title)}</summary><div class="detail-content"><span class="tag infer">${esc(q.kind)}</span><h4>工作假说</h4><p>${esc(q.claim)}</p><h4>真正的反方</h4><p>${esc(q.counter)}</p><h4>验证 / 证伪任务</h4><p>${esc(q.test)}</p><h4>所需数据</h4><p>${esc(q.data)}</p><div class="row between"><span>${refs(q.refs)}</span><button class="btn small" data-note-question="${q.id}">带入研究记录 ↗</button></div></div></details>`).join('')}</div>
